#!/usr/bin/env node
/**
 * Turn the LinkedIn drafts into something the CRM can render.
 *
 * Generated from the markdown rather than retyped, for the same reason the
 * language document is: a caption that exists in two places is a caption that
 * disagrees with itself within a week, and the one on screen is the one
 * nobody edits. The drafts stay the source; this is a build artefact.
 *
 * check-linkedin-posts.mjs fails if the generated file and the drafts have
 * drifted apart.
 *
 *   node scripts/build-linkedin-posts.mjs [--check]
 */
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const DRAFTS = resolve(ROOT, "..", "..", "SmartCareliving", "outreach", "linkedin-drafts");
const OUT = join(ROOT, "src/lib/crm/content/linkedin-posts.ts");
const PUBLIC = join(ROOT, "public/outreach/linkedin");

if (!existsSync(DRAFTS)) {
  console.error(`No drafts at ${DRAFTS}. Nothing regenerated; the committed file stands.`);
  process.exit(0);
}

const posts = [];
for (const name of readdirSync(DRAFTS).filter((f) => /^\d+ - .+\.md$/.test(f)).sort()) {
  const text = readFileSync(join(DRAFTS, name), "utf8");
  const [head, ...rest] = text.split(/\n---\n/);
  const body = rest.join("\n---\n").trim();

  const title = (/^#\s*\d+\.\s*(.+)$/m.exec(head)?.[1] ?? name).trim();
  const n = (/^#\s*(\d+)\./m.exec(head)?.[1] ?? "0").padStart(2, "0");
  /* The draft names its asset in a sentence. Take every filename it mentions
     and prefer the video, because a video is the post and the still is the
     fallback for a reader who will not press play. */
  const named = [...head.matchAll(/`([a-z0-9-]+\.(?:mp4|png))`/g)].map((m) => m[1]);
  const stem = named[0]?.replace(/\.(mp4|png)$/, "") ?? null;
  const close = (/Close type:\s*(.+)/.exec(head)?.[1] ?? "").trim();

  const video = stem && existsSync(join(PUBLIC, `${stem}.mp4`)) ? `/outreach/linkedin/${stem}.mp4` : null;
  const still = stem && existsSync(join(PUBLIC, `${stem}.png`)) ? `/outreach/linkedin/${stem}.png` : null;

  /* The hashtags are the last line and are not part of the caption's prose. */
  const lines = body.split("\n");
  const tagLine = lines[lines.length - 1]?.trim() ?? "";
  const tags = /^#\w/.test(tagLine) ? tagLine.split(/\s+/).filter(Boolean) : [];
  const caption = (tags.length ? lines.slice(0, -1) : lines).join("\n").trim();

  posts.push({ n, title, caption, tags, video, still, close,
    hook: caption.split("\n").find((l) => l.trim())?.trim() ?? "" });
}

const file =
  "/**\n" +
  " * Generated by scripts/build-linkedin-posts.mjs. Do not edit.\n" +
  " *\n" +
  " * Source: SmartCareliving/outreach/linkedin-drafts/*.md\n" +
  " * Assets: public/outreach/linkedin/\n" +
  " */\n\n" +
  "export interface LinkedInPost {\n" +
  "  n: string;\n  title: string;\n  hook: string;\n  caption: string;\n" +
  "  tags: string[];\n  video: string | null;\n  still: string | null;\n  close: string;\n}\n\n" +
  `export const LINKEDIN_POSTS: LinkedInPost[] = ${JSON.stringify(posts, null, 2)};\n`;

if (process.argv.includes("--check")) {
  const have = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
  if (have !== file) {
    console.error("The LinkedIn posts on screen no longer match the drafts they came from.");
    console.error("Run: node scripts/build-linkedin-posts.mjs");
    process.exit(1);
  }
  console.log(`${posts.length} LinkedIn posts, and the CRM copy matches the drafts.`);
  process.exit(0);
}

writeFileSync(OUT, file);
console.log(`${posts.length} posts written to ${OUT.replace(ROOT + "/", "")}`);
for (const p of posts) {
  console.log(`  ${p.n} ${p.title.padEnd(46)} ${p.video ? "mp4" : "   "} ${p.still ? "png" : "   "}`);
}
